import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import api from '../api';
import { useAuth } from '../context/AuthContext';
import Toast from '../components/Toast';
import { Mail, Lock, LogIn } from 'lucide-react';
import './Auth.css';

export default function Login() {
  const { login } = useAuth();
  const navigate = useNavigate();
  const [form, setForm] = useState({ email: '', password: '' });
  const [toast, setToast] = useState(null);
  const [loading, setLoading] = useState(false);

  const handle = e => setForm({ ...form, [e.target.name]: e.target.value });

  const submit = async () => {
    if (!form.email || !form.password)
      return setToast({ message: 'Please fill in all fields', type: 'error' });
    try {
      setLoading(true);
      const { data } = await api.post('/auth/login', form);
      login(data);
      navigate(data.role === 'admin' ? '/admin' : '/');
    } catch (err) {
      setToast({ message: err.response?.data?.message || 'Login failed', type: 'error' });
    } finally { setLoading(false); }
  };

  return (
    <div className="auth-page">
      {toast && <Toast {...toast} onClose={() => setToast(null)} />}
      <nav className="auth-nav">
        <Link to="/" className="nav-logo">
          <img src="/logo.png" alt="FINDRA" style={{ height: '40px', objectFit: 'contain' }} />
        </Link>
      </nav>
      <main className="auth-main">
        <div className="auth-hero">
          <div className="auth-hero-shapes">
            <div className="auth-blob ab1" />
            <div className="auth-blob ab2" />
          </div>
          <div className="auth-hero-text">
            <h2>Welcome Back!</h2>
            <p>Sign in to report lost items, track your found reports, and connect with your community.</p>
          </div>
        </div>
        <div className="auth-card">
          <h1 className="auth-title">Login</h1>
          <p className="auth-subtitle">Enter your credentials to continue</p>

          <div className="auth-input-group">
            <label>Email Address</label>
            <div className="auth-input-wrap">
              <Mail className="auth-input-icon" size={18} />
              <input name="email" type="email" className="auth-input with-icon" placeholder="you@example.com"
                value={form.email} onChange={handle} onKeyDown={e => e.key === 'Enter' && submit()} />
            </div>
          </div>
          <div className="auth-input-group">
            <label>Password</label>
            <div className="auth-input-wrap">
              <Lock className="auth-input-icon" size={18} />
              <input name="password" type="password" className="auth-input with-icon" placeholder="Your password"
                value={form.password} onChange={handle} onKeyDown={e => e.key === 'Enter' && submit()} />
            </div>
          </div>

          <div className="auth-actions">
            <button className="btn-auth-primary" onClick={submit} disabled={loading} style={{display:'flex', alignItems:'center', justifyContent:'center', gap:'8px'}}>
              {loading ? 'Signing in…' : <><LogIn size={18} /> Sign In</>}
            </button>
            <button className="btn-auth-outline" onClick={() => navigate('/signup')}>Sign Up</button>
          </div>

          <p className="auth-link">

          </p>
        </div>
      </main>
      <div className="auth-footer">© 2026 Lost and Found | All Rights Reserved</div>
    </div>
  );
}
